// === Tab: mySketch ===
let pg;
let pgSize;
let fontSize;
let particles = [];
let particlesNum = 500;
const palette = ["#f5321c", "#f0247e", "#29c0e4", "#0cba73", "#f8d243"];

function setup() {
	pgSize = windowWidth > windowHeight ? windowHeight : windowWidth;

	createCanvas(pgSize, pgSize);

	fontSize = pgSize * 0.425;

	pg = createGraphics(pgSize, pgSize);
	pg.textAlign(CENTER, CENTER);

	pg.fill(255);
	pg.noStroke();
	pg.rect(0, 0, pg.width, pg.height);

	pg.erase();

	pg.textSize(fontSize);
	pg.text(String.fromCodePoint(unhex('1F3BB')), pg.width / 4, pg.height / 4);
	pg.text(String.fromCodePoint(unhex('1F98B')), pg.width * 3 / 4, pg.height / 4);
	pg.text(String.fromCodePoint(unhex('1F940')), pg.width / 4, pg.height * 3 / 4);
	pg.text(String.fromCodePoint(unhex('1F3A0')), pg.width * 3 / 4, pg.height * 3 / 4);

	pg.noErase();

	imageMode(CENTER);
	for (let i = 0; i < particlesNum; i++) {
		particles.push(new Particle());
	}
}

function draw() {
	background(255);

	for (let i = 0; i < particles.length; i++) {
		particles[i].move();
		particles[i].display();
	}

	image(pg, width / 2, height / 2);
}

class Particle {
	constructor() {
		this.s = random(5, 50);
		this.x = random(width / 2 - pg.width / 2, width / 2 + pg.width / 2 - this.s);
		this.y = random(height / 2 - pg.height / 2, height / 2 + pg.height / 2 - this.s);

		this.speed = random(1, 3);
		this.sign = random(1) >= 0.5 ? -1 : 1;

		this.N = floor(random(2));
		this.c = random(palette);
	}

	move() {
		if (this.N == 0) {
			this.x += this.sign * this.speed;
		} else {
			this.y += this.sign * this.speed;
		}

		if (this.x < width / 2 - pg.width / 2 || this.x > width / 2 + pg.width / 2 - this.s ||
			this.y < height / 2 - pg.height / 2 || this.y > height / 2 + pg.height / 2 - this.s) {
			this.speed *= -1;
		}
	}

	display() {
		fill(this.c);
		noStroke();
		rect(this.x, this.y, this.s, this.s);
	}
}
